script:
card({ name: "Split the bill", icon: 'receipt' });
const words = {
  total: "Total {p0}",
  each: "{p0} each, split {p1} ways",
  owes: "Owes {p0}",
  getsBack: "Gets back {p0}",
  square: "All square",
  paid: "What you paid, like 12.50 pizza",
  join: "Count me in",
  undo: "Undo my last",
  nothing: "Nothing to undo",
  bad: "Start with an amount, like 12.50",
  empty: "Add what you paid. The card works out who owes what.",
  full: "That's a lot of payments. Start a new card.",
};

// Who paid what, split evenly between everyone in it.
function init() {
  return { people: {}, items: [] };
}

on.join = (s, args, ctx) => {
  s.people[ctx.author] = ctx.authorName;
};

on.paid = (s, args, ctx) => {
  const bits = String(args.value || '').trim().split(' ');
  const amount = parseFloat(bits[0].split(',').join('.'));
  if (!(amount > 0) || amount > 1000000) throw words.bad;
  if (s.items.length >= 200) throw words.full;
  s.people[ctx.author] = ctx.authorName;
  s.items.push({ by: ctx.author, amount: Math.round(amount * 100) / 100, what: bits.slice(1).join(' ').slice(0, 40) });
};

on.undo = (s, args, ctx) => {
  const i = s.items.findLastIndex(it => it.by === ctx.author);
  if (i < 0) throw words.nothing;
  s.items.splice(i, 1);
};

const money = n => n.toFixed(2);

function view(s) {
  const ids = Object.keys(s.people);
  const total = s.items.reduce((t, it) => t + it.amount, 0);
  const share = ids.length ? total / ids.length : 0;
  const parts = [];
  if (!s.items.length) parts.push(text(words.empty, { tone: 'muted' }));
  else {
    parts.push(text(words.total.replace('{p0}', money(total)), { size: 'large', bold: true, tone: 'accent' }));
    parts.push(text(words.each.replace('{p0}', money(share)).replace('{p1}', ids.length), { tone: 'muted', size: 'small' }));
  }
  for (const id of ids) {
    const paid = s.items.filter(it => it.by === id).reduce((t, it) => t + it.amount, 0);
    const diff = paid - share;
    const label = Math.abs(diff) < 0.005 ? words.square : diff > 0 ? words.getsBack.replace('{p0}', money(diff)) : words.owes.replace('{p0}', money(-diff));
    parts.push(row([text(s.people[id]), badge(label, { tone: Math.abs(diff) < 0.005 ? undefined : diff > 0 ? 'success' : 'warning' })], { align: 'between' }));
  }
  if (s.items.length) {
    parts.push(divider());
    for (const it of s.items.slice(-4).reverse()) {
      parts.push(text(s.people[it.by] + ': ' + money(it.amount) + (it.what ? ' · ' + it.what : ''), { size: 'small', tone: 'muted' }));
    }
  }
  parts.push(input('paid', words.paid, 'paid'));
  parts.push(row([button(words.join, 'join'), button(words.undo, 'undo', null, { tone: 'muted' })]));
  return column(parts);
}
